- (void)viewDidLoad{[super viewDidLoad];self.view.backgroundColor=[BTBackground() colorWithAlphaComponent:.97];_items=[NSMutableArray new];_results=[NSMutableDictionary new];_icons=[NSCache new];_icons.countLimit=32;_icons.totalCostLimit=1024*1024;NSArray *names=@[@"Media",@"Windows Apps",@"Quick Actions",@"Worker",@"Notifications",@"Connection & Settings"];_heading=BTLabel(25,UIFontWeightSemibold);_heading.text=names[self.kind];_subtitle=BTLabel(12,UIFontWeightRegular);_subtitle.textColor=BTMuted();_subtitle.text=self.kind==1?@"Your pinned PC applications":self.kind==2?@"Small commands. Real results.":self.kind==3?@"Work continues without taking over your screen.":self.kind==4?@"Recent events from your companion":@"USB first. Wireless only when you enable it.";[self.view addSubview:_heading];[self.view addSubview:_subtitle];
