- (UIButton *)textButton:(NSString *)title action:(SEL)action{UIButton *b=[UIButton buttonWithType:UIButtonTypeSystem];[b setTitle:title forState:UIControlStateNormal];b.titleLabel.font=[UIFont systemFontOfSize:14 weight:UIFontWeightMedium];b.tintColor=BTAccent();b.contentHorizontalAlignment=UIControlContentHorizontalAlignmentLeft;[b addTarget:self action:action forControlEvents:UIControlEventTouchUpInside];return b;}
- (void)buildSettings{_empty.hidden=YES;_settings=[UIScrollView new];[self.view addSubview:_settings];_connection=BTLabel(16,UIFontWeightSemibold);_connection.text=@"Disconnected";[_settings addSubview:_connection];_wifi=BTLabel(12,UIFontWeightRegular);_wifi.text=@"Temporary Wi-Fi is off";_wifi.textColor=BTMuted();[_settings addSubview:_wifi];_address=[UITextField new];_address.attributedPlaceholder=[[NSAttributedString alloc] initWithString:@"PC IPv4 address" attributes:@{NSForegroundColorAttributeName:BTMuted()}];_address.textColor=BTForeground();_address.backgroundColor=[UIColor colorWithWhite:1 alpha:.06];_address.layer.cornerRadius=8;_address.keyboardType=UIKeyboardTypeNumbersAndPunctuation;_address.autocorrectionType=UITextAutocorrectionTypeNo;_address.autocapitalizationType=UITextAutocapitalizationTypeNone;_address.accessibilityLabel=@"Windows PC address for temporary Wi-Fi";_address.text=[NSUserDefaults.standardUserDefaults stringForKey:@"wifiAddress"];[_settings addSubview:_address];_duration=[[UISegmentedControl alloc] initWithItems:@[@"15 min",@"30 min",@"Until off"]];_duration.selectedSegmentIndex=0;_duration.tintColor=BTAccent();[_settings addSubview:_duration];_enable=[self textButton:@"Enable Temporary Wi-Fi" action:@selector(enableWifi)];_disable=[self textButton:@"Disconnect Wi-Fi" action:@selector(disableWifi)];[_settings addSubview:_enable];[_settings addSubview:_disable];
