- (void)viewDidLayoutSubviews{[super viewDidLayoutSubviews];CGFloat w=self.view.bounds.size.width,h=self.view.bounds.size.height;_heading.frame=CGRectMake(28,20,w-110,34);_subtitle.frame=CGRectMake(29,58,w-90,22);_grid.frame=_list.frame=CGRectMake(28,95,w-56,h-113);_empty.frame=CGRectMake(50,110,w-100,h-160);if(_settings){_settings.frame=CGRectMake(29,94,w-58,h-108);CGFloat sw=_settings.bounds.size.width;_connection.frame=CGRectMake(0,0,sw,27);_wifi.frame=CGRectMake(0,30,sw,40);_address.frame=CGRectMake(0,79,sw*.52,40);_duration.frame=CGRectMake(sw*.55,82,sw*.45,34);_enable.frame=CGRectMake(0,126,240,44);_disable.frame=CGRectMake(sw-150,126,150,44);for(int i=0;i<3;i++){[_settings viewWithTag:100+i].frame=CGRectMake(0,188+i*53,sw-70,44);[_settings viewWithTag:200+i].frame=CGRectMake(sw-58,194+i*53,52,31);}for(int i=0;i<3;i++)[_settings viewWithTag:302+i].frame=CGRectMake(0,355+i*49,sw,44);[_settings viewWithTag:400].frame=CGRectMake(0,520,sw,42);_settings.contentSize=CGSizeMake(sw,580);}}
- (void)setConnected:(BOOL)connected{_connected=connected;_connection.text=connected?@"Companion connected":@"Disconnected";_enable.enabled=connected&&[self.transport isEqual:@"USB"];[_grid reloadData];}
- (void)setTransport:(NSString *)transport{_transport=[transport copy];_enable.enabled=_connected&&[transport isEqual:@"USB"];}
- (void)send:(NSString *)type body:(NSDictionary *)body{if(self.command)self.command(type,body);}
- (void)enableWifi{[self.view endEditing:YES];NSString *address=[_address.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];[NSUserDefaults.standardUserDefaults setObject:address forKey:@"wifiAddress"];[self send:@"wifi.enable" body:@{@"address":address?:@"",@"minutes":@(_duration.selectedSegmentIndex==0?15:_duration.selectedSegmentIndex==1?30:0),@"fallback":@([NSUserDefaults.standardUserDefaults boolForKey:@"wifiFallback"])}];_wifi.text=@"Requesting an authorized temporary session…";}
- (void)disableWifi{[self send:@"wifi.disable" body:@{}];}
- (void)preference:(UISwitch *)sender{NSString *key=sender.accessibilityIdentifier;if([key isEqual:@"criticalFullscreen"])[NSUserDefaults.standardUserDefaults setBool:!sender.on forKey:@"disableCriticalFullscreen"];else [NSUserDefaults.standardUserDefaults setBool:sender.on forKey:key];[self send:@"settings.changed" body:@{@"key":key,@"value":@(sender.on)}];}
- (void)settingAction:(UIButton *)button{if(button.tag<=301){NSString *key=button.tag==300?@"fullscreenSources":@"fullscreenCategories";UIAlertController *alert=[UIAlertController alertControllerWithTitle:button.currentTitle message:@"Comma-separated exact source/category names. Selected sources/categories use fullscreen; other events retain their priority presentation." preferredStyle:UIAlertControllerStyleAlert];[alert addTextFieldWithConfigurationHandler:^(UITextField *f){f.text=[[NSUserDefaults.standardUserDefaults arrayForKey:key] componentsJoinedByString:@", "];f.autocorrectionType=UITextAutocorrectionTypeNo;}];[alert addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]];[alert addAction:[UIAlertAction actionWithTitle:@"Save" style:UIAlertActionStyleDefault handler:^(UIAlertAction *a){(void)a;NSMutableArray *values=[NSMutableArray new];for(NSString *part in [alert.textFields.firstObject.text componentsSeparatedByString:@","]){NSString *value=[part stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];if(value.length&&value.length<=128&&values.count<32)[values addObject:value];}[NSUserDefaults.standardUserDefaults setObject:values forKey:key];}]];[self presentViewController:alert animated:YES completion:nil];}else [self send:button.tag==302?@"media.open":button.tag==303?@"media.pc":@"pair" body:@{}];}
- (void)receive:(NSString *)type body:(NSDictionary *)body{[self loadViewIfNeeded];if(_reordering&&([type isEqual:@"apps.catalog"]||[type isEqual:@"action.registry"])){[_grid cancelInteractiveMovement];_reordering=NO;if(self.interactionChanged)self.interactionChanged(NO);}
    if([type isEqual:@"apps.catalog"]&&self.kind==1){if([body[@"reset"] boolValue])[_items removeAllObjects];for(NSDictionary *item in body[@"apps"]){if(_items.count>=32)break;if([item isKindOfClass:NSDictionary.class]&&[item[@"id"] isKindOfClass:NSString.class]){NSUInteger old=[_items indexOfObjectPassingTest:^BOOL(NSDictionary *x,NSUInteger i,BOOL *stop){(void)i;(void)stop;return [x[@"id"] isEqual:item[@"id"]];}];if(old!=NSNotFound)_items[old]=item;else [_items addObject:item];}}[_grid reloadData];}
    else if([type isEqual:@"action.registry"]&&self.kind==2){[_items removeAllObjects];for(NSDictionary *item in body[@"actions"]){if(_items.count>=32)break;if([item isKindOfClass:NSDictionary.class]&&[item[@"id"] isKindOfClass:NSString.class])[_items addObject:item];}NSArray *saved=[NSUserDefaults.standardUserDefaults arrayForKey:@"actions.order"];if(saved.count){[_items sortUsingComparator:^NSComparisonResult(NSDictionary *a,NSDictionary *b){NSUInteger ai=[saved indexOfObject:a[@"id"]],bi=[saved indexOfObject:b[@"id"]];if(ai==bi)return NSOrderedSame;return ai<bi?NSOrderedAscending:NSOrderedDescending;}];}[_grid reloadData];}
