    else if([type isEqual:@"command.result"]){NSString *identifier=BTString(body[@"appId"],BTString(body[@"actionId"],@""));if(identifier.length)_results[identifier]=[body[@"ok"] boolValue]?@"Confirmed":BTString(body[@"error"],@"Failed");[_grid reloadData];}
    else if([type isEqual:@"wifi.state"]&&self.kind==5){_wifiBase=BTString(body[@"state"],@"Wi-Fi unavailable");double remaining=BTDouble(body[@"remainingSeconds"]);_wifiDeadline=remaining>0?BTSessionClock()+remaining:0;_disable.enabled=[body[@"enabled"] boolValue];[self refreshCountdown];if(!_countdown){__weak typeof(self) weak=self;_countdown=[NSTimer scheduledTimerWithTimeInterval:1 repeats:YES block:^(NSTimer *timer){(void)timer;[weak refreshCountdown];}];}}
    _empty.hidden=_items.count>0||self.kind==5;
}
- (NSInteger)collectionView:(UICollectionView *)view numberOfItemsInSection:(NSInteger)section{(void)view;(void)section;return _items.count;}
- (CGSize)collectionView:(UICollectionView *)view layout:(UICollectionViewLayout *)layout sizeForItemAtIndexPath:(NSIndexPath *)path{(void)layout;(void)path;CGFloat width=view.bounds.size.width;NSInteger columns=MAX(2,(NSInteger)(width/115));return CGSizeMake(floor((width-(columns-1)*12)/columns),118);}
- (UIImage *)icon:(NSDictionary *)item{NSString *version=BTString(item[@"iconVersion"],BTString(item[@"id"],@""));UIImage *image=[_icons objectForKey:version];NSString *encoded=BTString(item[@"iconBase64"],@"");if(!image&&encoded.length&&encoded.length<=12000){NSData *data=[[NSData alloc] initWithBase64EncodedString:encoded options:0];CGImageSourceRef source=data?CGImageSourceCreateWithData((__bridge CFDataRef)data,NULL):NULL;if(source){CGImageRef thumbnail=CGImageSourceCreateThumbnailAtIndex(source,0,(__bridge CFDictionaryRef)@{(id)kCGImageSourceCreateThumbnailFromImageAlways:@YES,(id)kCGImageSourceThumbnailMaxPixelSize:@64});if(thumbnail){image=[UIImage imageWithCGImage:thumbnail];[_icons setObject:image forKey:version cost:64*64*4];CGImageRelease(thumbnail);}CFRelease(source);}}return image?:BTGlyph(BTString(item[@"icon"],self.kind==1?@"apps":@"actions"));}
- (UICollectionViewCell *)collectionView:(UICollectionView *)view cellForItemAtIndexPath:(NSIndexPath *)path{BTActionCell *cell=[view dequeueReusableCellWithReuseIdentifier:@"tile" forIndexPath:path];NSDictionary *item=_items[path.item];cell.icon.image=[self icon:item];cell.title.text=BTString(item[@"title"],@"App");cell.detail.text=_results[item[@"id"]]?:(_connected?@"":@"Offline");cell.contentView.alpha=_connected&&(!item[@"available"]||[item[@"available"] boolValue])?1:.4;cell.accessibilityLabel=[NSString stringWithFormat:@"%@, %@",cell.title.text,cell.detail.text];cell.accessibilityTraits=UIAccessibilityTraitButton|(_connected?0:UIAccessibilityTraitNotEnabled);cell.accessibilityHint=self.kind==1?@"Launch on Windows. Hold to reorder.":@"Run approved action. Hold to reorder.";return cell;}
- (void)collectionView:(UICollectionView *)view didSelectItemAtIndexPath:(NSIndexPath *)path{(void)view;NSDictionary *item=_items[path.item];if(!_connected||(item[@"available"]&&![item[@"available"] boolValue]))return;_results[item[@"id"]]=@"Sending…";[_grid reloadItemsAtIndexPaths:@[path]];[self send:self.kind==1?@"apps.launch":@"action.invoke" body:@{(self.kind==1?@"appId":@"actionId"):item[@"id"]}];}
- (void)reorder:(UILongPressGestureRecognizer *)gesture{CGPoint p=[gesture locationInView:_grid];if(gesture.state==UIGestureRecognizerStateBegan){NSIndexPath *path=[_grid indexPathForItemAtPoint:p];if(path)_reordering=[_grid beginInteractiveMovementForItemAtIndexPath:path];if(_reordering&&self.interactionChanged)self.interactionChanged(YES);}else if(gesture.state==UIGestureRecognizerStateChanged){if(_reordering)[_grid updateInteractiveMovementTargetPosition:p];}else{if(_reordering){if(gesture.state==UIGestureRecognizerStateEnded)[_grid endInteractiveMovement];else [_grid cancelInteractiveMovement];}_reordering=NO;if(self.interactionChanged)self.interactionChanged(NO);}}
- (BOOL)collectionView:(UICollectionView *)view canMoveItemAtIndexPath:(NSIndexPath *)path{(void)view;(void)path;return YES;}
- (void)collectionView:(UICollectionView *)view moveItemAtIndexPath:(NSIndexPath *)source toIndexPath:(NSIndexPath *)destination{(void)view;id item=_items[source.item];[_items removeObjectAtIndex:source.item];[_items insertObject:item atIndex:destination.item];NSArray *ids=[_items valueForKey:@"id"];[NSUserDefaults.standardUserDefaults setObject:ids forKey:self.kind==1?@"apps.order":@"actions.order"];if(self.kind==1)[self send:@"apps.order" body:@{@"appIds":ids}];}
- (NSInteger)tableView:(UITableView *)tableView numberOfRowsInSection:(NSInteger)section{(void)tableView;(void)section;return _items.count;}
- (UITableViewCell *)tableView:(UITableView *)tableView cellForRowAtIndexPath:(NSIndexPath *)path{UITableViewCell *cell=[tableView dequeueReusableCellWithIdentifier:@"row"];if(!cell)cell=[[UITableViewCell alloc] initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:@"row"];cell.backgroundColor=UIColor.clearColor;cell.textLabel.textColor=BTForeground();cell.textLabel.font=[UIFont systemFontOfSize:15 weight:UIFontWeightMedium];cell.detailTextLabel.textColor=BTMuted();cell.detailTextLabel.numberOfLines=2;cell.detailTextLabel.font=[UIFont systemFontOfSize:12];cell.imageView.tintColor=BTAccent();NSDictionary *item=_items[path.row];cell.imageView.image=BTGlyph(self.kind==3?@"worker":@"bell");cell.accessoryView=nil;if(self.kind==3){cell.textLabel.text=[NSString stringWithFormat:@"%@ · %.0f%%",BTString(item[@"state"],@"Job"),BTDouble(item[@"progress"])*100];cell.detailTextLabel.text=BTString(item[@"error"],BTString(item[@"jobId"],@""));if([@[@"running",@"queued"] containsObject:item[@"state"]]){UIButton *cancel=BTButton(@"close",@"Cancel job",self,@selector(cancelJob:));cancel.frame=CGRectMake(0,0,44,44);cancel.accessibilityIdentifier=BTString(item[@"jobId"],@"");cell.accessoryView=cancel;}}else{cell.textLabel.text=BTString(item[@"title"],@"");cell.detailTextLabel.text=[NSString stringWithFormat:@"%@ · %@",BTString(item[@"source"],@""),BTString(item[@"body"],@"")];}return cell;}
